/**
 * Unit tests for CoreFunction.functionCeiling
 */
public class CoreFunction_functionCeiling_TriageGen1Test {

    private EvalContext mockContext;
    private Expression mockArg1;

    @Before
    public void setUp() {
        mockContext = mock(EvalContext.class);
        mockArg1 = mock(Expression.class);
    }

    /**
     * Test ceiling with a positive decimal number.
     */
    @Test
    public void testFunctionCeiling_PositiveDecimal() throws Throwable {
        // Setup: CoreFunction with 1 argument
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        // Mock behavior: arg1.computeValue(context) returns 2.3
        when(mockArg1.computeValue(mockContext)).thenReturn(2.3);

        // Execute
        Object result = invokeFunctionCeiling(function, mockContext);

        // Verify: ceil(2.3) = 3.0
        assertEquals(3.0, (Double) result, 0.0001);
    }

    /**
     * Test ceiling with a negative decimal number.
     */
    @Test
    public void testFunctionCeiling_NegativeDecimal() throws Throwable {
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        // Mock behavior: arg1.computeValue(context) returns -2.3
        when(mockArg1.computeValue(mockContext)).thenReturn(-2.3);

        // Execute
        Object result = invokeFunctionCeiling(function, mockContext);

        // Verify: ceil(-2.3) = -2.0
        assertEquals(-2.0, (Double) result, 0.0001);
    }

    /**
     * Test ceiling with an integer value.
     */
    @Test
    public void testFunctionCeiling_Integer() throws Throwable {
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        // Mock behavior: arg1.computeValue(context) returns 5.0
        when(mockArg1.computeValue(mockContext)).thenReturn(5.0);

        // Execute
        Object result = invokeFunctionCeiling(function, mockContext);

        // Verify: ceil(5.0) = 5.0
        assertEquals(5.0, (Double) result, 0.0001);
    }

    /**
     * Test ceiling with zero.
     */
    @Test
    public void testFunctionCeiling_Zero() throws Throwable {
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        // Mock behavior: arg1.computeValue(context) returns 0.0
        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        // Execute
        Object result = invokeFunctionCeiling(function, mockContext);

        // Verify: ceil(0.0) = 0.0
        assertEquals(0.0, (Double) result, 0.0001);
    }

    /**
     * Test ceiling with Infinity.
     */
    @Test
    public void testFunctionCeiling_Infinity() throws Throwable {
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(Double.POSITIVE_INFINITY);

        Object result = invokeFunctionCeiling(function, mockContext);

        assertEquals(Double.POSITIVE_INFINITY, (Double) result, 0.0);
    }

    /**
     * Test ceiling with NaN.
     */
    @Test
    public void testFunctionCeiling_NaN() throws Throwable {
        Expression[] args = new Expression[]{mockArg1};
        CoreFunction function = new CoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(Double.NaN);

        Object result = invokeFunctionCeiling(function, mockContext);

        assertEquals(Double.NaN, (Double) result, 0.0);
    }

    /**
     * Helper method to access the protected method functionCeiling via reflection.
     * Since we want to test the exact method logic.
     */
    private Object invokeFunctionCeiling(CoreFunction function, EvalContext context) throws Exception {
        java.lang.reflect.Method method = CoreFunction.class.getDeclaredMethod("functionCeiling", EvalContext.class);
        method.setAccessible(true);
        return method.invoke(function, context);
    }
}
